from fractions import Fraction

def get_reachable_with_count(m, n, max_elements=2000):
    s = {Fraction(m, n), Fraction(n, m)}
    changed = True
    count = 0
    while changed and len(s) < max_elements:
        changed = False
        new_elements = set()
        elements = list(s)
        for i in range(len(elements)):
            for j in range(i + 1, len(elements)):
                x, y = elements[i], elements[j]
                am = (x + y) / 2
                hm = (2 * x * y) / (x + y)
                if am not in s:
                    new_elements.add(am)
                if hm not in s:
                    new_elements.add(hm)
        if new_elements:
            s.update(new_elements)
            changed = True
            count += 1
        if Fraction(1, 1) in s:
            return True, len(s)
    return Fraction(1, 1) in s, len(s)

